import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures readiness before frame 0
const { fontFamily: interFamily } = loadInter();



export type IMessageChatProps = Record<string, any>;

const IMessageChat: React.FC<IMessageChatProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 15,
  dateText = "Wed, Dec 17 2026",
  message1 = "I am trying a new version of an event inspired by what I did at your wedding!",
  message2 = "We wil do Asian dinners, and the idea is that I visualize through data who is around the table",
  message3 = "So you come seeing the room.",
  accentColor = "#007AFF",
  keyboardColor = "#D1D4D9",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timeline Configuration
  const script = [
    {
      text: message1,
      startTyping: 1 * fps,
      endTyping: 3 * fps,
      send: 3.5 * fps,
    },
    {
      text: message2,
      startTyping: 4.5 * fps,
      endTyping: 7 * fps,
      send: 7.5 * fps,
    },
    {
      text: message3,
      startTyping: 8.5 * fps,
      endTyping: 10 * fps,
      send: 10.5 * fps,
    },
  ];

  const reactionFrame = 11.5 * fps;

  // Derive State from Frame
  let currentInput = "iMessage";
  let isPlaceholder = true;
  const sentMessages = [];

  for (let i = 0; i < script.length; i++) {
    const item = script[i];
    
    // Check if message is sent
    if (frame >= item.send) {
      sentMessages.push({ ...item, id: i });
    } 
    // Check if message is currently being typed/held before sending
    else if (frame >= item.startTyping && frame < item.send) {
      isPlaceholder = false;
      if (frame < item.endTyping) {
        const charCount = Math.floor(
          interpolate(frame, [item.startTyping, item.endTyping], [0, item.text.length], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          })
        );
        currentInput = item.text.substring(0, charCount);
      } else {
        currentInput = item.text;
      }
    }
  }

  // Layout Measurements
  const keyboardHeight = height * 0.32; // ~614px
  const chatBottomOffset = keyboardHeight + 180; // Expanded to accommodate multiline input

  const row1 = ['Q','W','E','R','T','Y','U','I','O','P'];
  const row2 = ['A','S','D','F','G','H','J','K','L'];
  const row3 = ['Z','X','C','V','B','N','M'];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* 1. Chat History Area */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: height - chatBottomOffset,
          display: "flex",
          flexDirection: "column",
          justifyContent: "flex-end",
          padding: "80px 40px 40px 40px",
          boxSizing: "border-box",
          gap: "24px",
          transition: "none",
        }}
      >
        {/* Date Header (Pill Style) */}
        <div style={{ textAlign: "center", marginBottom: "auto", marginTop: "40px" }}>
          <span style={{ 
            fontSize: "26px", 
            color: "#333333", 
            fontWeight: 600,
            backgroundColor: "#FFFFFF",
            padding: "10px 32px",
            borderRadius: "40px",
            boxShadow: "0 4px 16px rgba(0,0,0,0.08)",
            display: "inline-block"
          }}>
            {dateText}
          </span>
        </div>

        {/* Render Sent Messages */}
        {sentMessages.map((msg, index) => {
          const isLast = index === sentMessages.length - 1;
          const scale = spring({
            frame: frame - msg.send,
            fps,
            config: { damping: 14, stiffness: 120 },
          });

          return (
            <div
              key={msg.id}
              style={{
                alignSelf: "flex-end",
                maxWidth: "75%",
                backgroundColor: accentColor,
                padding: "24px 36px",
                borderRadius: "40px",
                borderBottomRightRadius: "8px",
                color: "#FFFFFF",
                fontSize: "36px",
                lineHeight: "1.4",
                transform: `scale(${scale})`,
                transformOrigin: "bottom right",
                position: "relative",
                boxShadow: "0 6px 16px rgba(0,0,0,0.15)", // Added more noticeable drop shadow
                transition: "none",
              }}
            >
              {msg.text}

              {/* Message Tail SVG */}
              <svg 
                width="30" 
                height="30" 
                viewBox="0 0 30 30" 
                style={{ 
                  position: "absolute", 
                  right: -12, 
                  bottom: 0,
                  zIndex: -1
                }}
              >
                <path d="M 0 30 C 15 30 30 15 30 0 L 30 30 Z" fill={accentColor} />
              </svg>

              {/* Heart Reaction for Message 3 (index 2) */}
              {msg.id === 2 && frame >= reactionFrame && (
                <div
                  style={{
                    position: "absolute",
                    top: -40,
                    left: -20,
                    width: "80px",
                    height: "80px",
                    backgroundColor: "#E5E5EA",
                    borderRadius: "40px",
                    border: `6px solid ${backgroundColor}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: "40px",
                    transform: `scale(${spring({
                      frame: frame - reactionFrame,
                      fps,
                      config: { damping: 12, stiffness: 150 },
                    })})`,
                    zIndex: 10,
                    transition: "none",
                  }}
                >
                  ❤️
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* 2. Input Field Area */}
      <div
        style={{
          position: "absolute",
          bottom: keyboardHeight,
          left: 0,
          width: "100%",
          minHeight: 140, // Changed from fixed height to allow expansion
          display: "flex",
          alignItems: "flex-end", // Anchors content to the bottom as it grows
          padding: "30px 40px",
          boxSizing: "border-box",
          backgroundColor: backgroundColor,
          borderTop: `2px solid ${keyboardColor}80`,
          transition: "none",
        }}
      >
        <div
          style={{
            flex: 1,
            minHeight: "80px", // Allows vertical growth
            border: "3px solid #E5E5EA",
            borderRadius: "40px", // Pill shape
            display: "flex",
            alignItems: "flex-end", // Keeps camera and send button at the bottom
            padding: "7px 7px 7px 20px",
            gap: "20px",
            backgroundColor: "#FFFFFF",
            boxSizing: "border-box",
          }}
        >
          {/* Mock Camera/App Icon */}
          <div style={{ 
            width: "40px", 
            height: "40px", 
            borderRadius: "20px", 
            backgroundColor: "#E5E5EA", 
            flexShrink: 0,
            marginBottom: "10px" // Vertically centers with the 60px send button
          }} />
          
          {/* Text Content */}
          <div
            style={{
              flex: 1,
              whiteSpace: "pre-wrap", // Enabled multiple lines
              wordBreak: "break-word",
              fontSize: "36px",
              lineHeight: "1.25",
              color: isPlaceholder ? "#8E8E93" : "#000000",
              padding: "10px 0",
              marginBottom: "3px",
            }}
          >
            {currentInput}
          </div>

          {/* Send Button */}
          <div
            style={{
              width: "60px",
              height: "60px",
              borderRadius: "30px",
              backgroundColor: !isPlaceholder ? accentColor : "#E5E5EA",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
              transition: "none",
            }}
          >
            {/* Up Arrow SVG */}
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
              <path d="M12 20V4M12 4L5 11M12 4L19 11" stroke="#FFFFFF" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </div>
        </div>
      </div>

      {/* 3. Keyboard Mockup */}
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          width: "100%",
          height: keyboardHeight,
          backgroundColor: keyboardColor,
          display: "flex",
          flexDirection: "column",
          padding: "30px 20px",
          boxSizing: "border-box",
          gap: "24px",
          transition: "none",
        }}
      >
        {/* Row 1 */}
        <div style={{ display: "flex", gap: "12px", height: "90px" }}>
          {row1.map((char, i) => (
            <div key={`r1-${i}`} style={keyStyle}>{char}</div>
          ))}
        </div>
        
        {/* Row 2 */}
        <div style={{ display: "flex", gap: "12px", height: "90px", padding: "0 40px" }}>
          {row2.map((char, i) => (
            <div key={`r2-${i}`} style={keyStyle}>{char}</div>
          ))}
        </div>
        
        {/* Row 3 */}
        <div style={{ display: "flex", gap: "12px", height: "90px" }}>
          <div style={{ ...keyStyle, flex: 1.5, backgroundColor: "#AEAFB4", fontSize: "40px" }}>⇧</div>
          {row3.map((char, i) => (
            <div key={`r3-${i}`} style={keyStyle}>{char}</div>
          ))}
          <div style={{ ...keyStyle, flex: 1.5, backgroundColor: "#AEAFB4", fontSize: "32px" }}>⌫</div>
        </div>
        
        {/* Row 4 */}
        <div style={{ display: "flex", gap: "12px", height: "90px" }}>
          <div style={{ ...keyStyle, flex: 2.5, backgroundColor: "#AEAFB4", fontSize: "28px" }}>123</div>
          <div style={{ ...keyStyle, flex: 5, fontSize: "28px" }}>space</div>
          <div style={{ ...keyStyle, flex: 2.5, backgroundColor: "#AEAFB4", fontSize: "28px" }}>return</div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

const keyStyle: React.CSSProperties = {
  flex: 1,
  backgroundColor: "#FFFFFF",
  borderRadius: "16px",
  boxShadow: "0px 3px 0px 0px #898A8D",
  transition: "none",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  fontSize: "36px",
  fontWeight: 400,
  color: "#000000",
};

export default IMessageChat;